package main

import (
	"math/bits"

	"github.com/corentings/chess/v2"
)

// Original starting coefficients, fixed before the match screen. No learned
// weights or game-history terms. Features can be isolated in offline tests.
type positionalFeatures uint8

const (
	pawnStructure positionalFeatures = 1 << iota
	kingShelter
	minorActivity
	candidateFeatures = pawnStructure | kingShelter
)

type evaluationBoard struct {
	pieces      [64]chess.Piece
	pawns       [3][8]uint8 // Rank bits on each file, by color.
	pawnAttacks [3]uint64
	kings       [3]int
	heavy       [3]int // Rooks and queens, for open-file danger near kings.
	phase       int
}

type evaluationTerms struct {
	material, placement, pawns, shelter, activity, phase int
}

func (terms evaluationTerms) total() int {
	return terms.material + terms.placement + terms.pawns + terms.shelter + terms.activity
}

func tapered(middle, ending, phase int) int {
	return (middle*phase + ending*(24-phase)) / 24
}

func summarizeBoard(position *chess.Position) evaluationBoard {
	result := evaluationBoard{kings: [3]int{-1, -1, -1}}
	var pawns [3]uint64
	for square := chess.A1; square <= chess.H8; square++ {
		piece := position.Board().Piece(square)
		result.pieces[square] = piece
		if piece == chess.NoPiece {
			continue
		}
		side := piece.Color()
		result.phase += phaseWeight(piece.Type())
		switch piece.Type() {
		case chess.Pawn:
			result.pawns[side][int(square)%8] |= 1 << (int(square) / 8)
			pawns[side] |= uint64(1) << square
		case chess.King:
			result.kings[side] = int(square)
		case chess.Rook, chess.Queen:
			result.heavy[side]++
		}
	}
	const aFile uint64 = 0x0101010101010101
	const hFile uint64 = 0x8080808080808080
	result.pawnAttacks[chess.White] = (pawns[chess.White]&^aFile)<<7 | (pawns[chess.White]&^hFile)<<9
	result.pawnAttacks[chess.Black] = (pawns[chess.Black]&^aFile)>>9 | (pawns[chess.Black]&^hFile)>>7
	result.phase = min(24, result.phase)
	return result
}

func (board *evaluationBoard) pawnScore(side chess.Color) (middle, ending int) {
	for file, ranks := range board.pawns[side] {
		if ranks == 0 {
			continue
		}
		count := bits.OnesCount8(ranks)
		middle -= 12 * (count - 1)
		ending -= 18 * (count - 1)
		if (file == 0 || board.pawns[side][file-1] == 0) && (file == 7 || board.pawns[side][file+1] == 0) {
			middle -= 10 * count
			ending -= 12 * count
		}
		for ranks != 0 {
			rank := bits.TrailingZeros8(ranks)
			ranks &= ranks - 1
			forward := 1
			ahead := uint8(0xff << (rank + 1))
			relative := rank
			if side == chess.Black {
				forward, ahead, relative = -1, uint8((1<<rank)-1), 7-rank
			}
			// Only the foremost friendly pawn on a file gets passer credit.
			passed := board.pawns[side][file]&ahead == 0
			for adjacent := max(0, file-1); adjacent <= min(7, file+1); adjacent++ {
				passed = passed && board.pawns[side.Other()][adjacent]&ahead == 0
			}
			if !passed {
				continue
			}
			advance := min(6, relative)
			mg, eg := 2*advance*advance, 4*advance*advance
			nextRank := rank + forward
			if nextRank >= 0 && nextRank < 8 && board.pieces[nextRank*8+file] != chess.NoPiece {
				mg, eg = mg/2, eg/2
			}
			middle, ending = middle+mg, ending+eg
		}
	}
	return middle, ending
}

// Shelter is a middlegame term. Existing endgame king placement is retained.
func (board *evaluationBoard) shelterScore(side chess.Color) int {
	square := board.kings[side]
	if square < 0 {
		return 0
	}
	file, rank := square%8, square/8
	forward := 1
	if side == chess.Black {
		forward = -1
	}
	score := 0
	for adjacent := max(0, file-1); adjacent <= min(7, file+1); adjacent++ {
		for distance := 1; distance <= 2; distance++ {
			nextRank := rank + forward*distance
			if nextRank >= 0 && nextRank < 8 && board.pawns[side][adjacent]&(1<<nextRank) != 0 {
				score += 14 / distance
				break // Do not double-count a doubled shield on one file.
			}
		}
		if board.heavy[side.Other()] > 0 && board.pawns[side][adjacent] == 0 {
			score -= 12
			if board.pawns[side.Other()][adjacent] == 0 {
				score -= 8
			}
		}
	}
	return score
}

// Pseudo-legal destinations, excluding friendly occupancy and enemy pawn
// attacks. Pins, other attackers, and king legality are intentionally not
// modeled: this is a small activity preference, not legal or safe move count.
func (board *evaluationBoard) mobility(square int) int {
	piece := board.pieces[square]
	x, y := square%8, square/8
	count := 0
	available := func(file, rank int) bool {
		target := rank*8 + file
		return board.pieces[target].Color() != piece.Color() && board.pawnAttacks[piece.Color().Other()]&(uint64(1)<<target) == 0
	}
	if piece.Type() == chess.Knight {
		for _, offset := range [8][2]int{{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}} {
			file, rank := x+offset[0], y+offset[1]
			if file >= 0 && file < 8 && rank >= 0 && rank < 8 && available(file, rank) {
				count++
			}
		}
	}
	if piece.Type() == chess.Bishop {
		for _, direction := range [4][2]int{{-1, -1}, {-1, 1}, {1, -1}, {1, 1}} {
			for file, rank := x+direction[0], y+direction[1]; file >= 0 && file < 8 && rank >= 0 && rank < 8; file, rank = file+direction[0], rank+direction[1] {
				if available(file, rank) {
					count++
				}
				if board.pieces[rank*8+file] != chess.NoPiece {
					break
				}
			}
		}
	}
	return count
}

func positionalEvaluation(position *chess.Position, perspective chess.Color, features positionalFeatures) evaluationTerms {
	board := summarizeBoard(position)
	terms := evaluationTerms{phase: board.phase}
	for square, piece := range board.pieces {
		if piece == chess.NoPiece {
			continue
		}
		sign, rank := 1, square/8
		if piece.Color() == chess.Black {
			sign, rank = -1, 7-rank
		}
		terms.material += sign * pieceValues[piece.Type()]
		terms.placement += sign * placement(piece.Type(), square%8, rank, board.phase)
		if features&minorActivity != 0 && (piece.Type() == chess.Knight || piece.Type() == chess.Bishop) {
			weight := 3
			if piece.Type() == chess.Knight {
				weight = 4
			}
			terms.activity += sign * weight * board.mobility(square)
		}
	}
	if features&pawnStructure != 0 {
		wm, we := board.pawnScore(chess.White)
		bm, be := board.pawnScore(chess.Black)
		terms.pawns = tapered(wm-bm, we-be, board.phase)
	}
	if features&kingShelter != 0 {
		terms.shelter = tapered(board.shelterScore(chess.White)-board.shelterScore(chess.Black), 0, board.phase)
	}
	if perspective == chess.Black {
		terms.material, terms.placement, terms.pawns, terms.shelter, terms.activity = -terms.material, -terms.placement, -terms.pawns, -terms.shelter, -terms.activity
	}
	return terms
}

